/*
* Private helpers adapted from Reference-LAPACK at commit
* 2e5d9c1273435fbd953adb294ed603e4789afaba: BLAS/SRC/idamax.f
* (blob 35042300d7e06b1130f850feef515e027149a4f6) and BLAS/SRC/dger.f
* (blob 24a6d86bb28f48d489b4fd15d3281a83672c7a91). DGER was written
* 22-October-1986 by Jack Dongarra (Argonne National Lab.), Jeremy Du Croz
* and Sven Hammarling (NAG Central Office), and Richard Hanson (Sandia
* National Labs.). Full pinned BSD terms are retained in dgbtf2_ndarray.c.
*/

#ifndef STDLIB_LAPACK_BASE_DGBTF2_PANEL_H
#define STDLIB_LAPACK_BASE_DGBTF2_PANEL_H

#include "stdlib/blas/base/dscal.h"
#include "stdlib/blas/base/dswap.h"
#include <math.h>
#include <stdint.h>

typedef struct dgbtf2_view {
	double *data;
	intmax_t stride1;
	intmax_t stride2;
	intmax_t offset;
} dgbtf2_view;

/**
* Computes a fully prevalidated band's zero-based cell index.
*/
static intmax_t dgbtf2_index( const dgbtf2_view *ab, const intmax_t row, const intmax_t column ) {
	return ab->offset+row*ab->stride1+column*ab->stride2;
}

#define DGBTF2_CELL( ab, row, column ) ( (ab)->data[ dgbtf2_index( (ab), (row), (column) ) ] )

/**
* Returns the first logical absolute maximum without allocating.
*/
static intmax_t dgbtf2_first_absmax( const intmax_t count, const dgbtf2_view *ab, const intmax_t row, const intmax_t column ) {
	intmax_t winner;
	intmax_t i;
	double maximum;
	double value;

	if ( count <= 0 ) return -1;
	maximum = fabs( DGBTF2_CELL( ab, row, column ) );
	winner = 0;
	for ( i = 1; i < count; i++ ) {
		value = fabs( DGBTF2_CELL( ab, row+i, column ) );
		if ( value > maximum ) {
			maximum = value;
			winner = i;
		}
	}
	return winner;
}

/**
* Swaps diagonal band fragments with the actual existing DSWAP adapter.
*
* Counts are checked before indices or pointers are formed. Singleton
* unused strides normalize to one; all other casts/trips are preflighted.
*/
static void dgbtf2_swap( const intmax_t count, dgbtf2_view *ab, const intmax_t rowX, const intmax_t rowY, const intmax_t column ) {
	intmax_t offsetX;
	intmax_t offsetY;
	intmax_t stride;

	if ( count <= 0 ) return;
	offsetX = dgbtf2_index( ab, rowX, column );
	offsetY = dgbtf2_index( ab, rowY, column );
	stride = count == 1 ? 1 : ab->stride2-ab->stride1;
	API_SUFFIX(c_dswap_ndarray)( (CBLAS_INT)count, ab->data+offsetX, (CBLAS_INT)stride, 0, ab->data+offsetY, (CBLAS_INT)stride, 0 );
}

/**
* Scales a band-column fragment with the actual existing DSCAL adapter.
*/
static void dgbtf2_scale( const intmax_t count, const double alpha, dgbtf2_view *ab, const intmax_t row, const intmax_t column ) {
	intmax_t offset;
	intmax_t stride;

	if ( count <= 0 ) return;
	offset = dgbtf2_index( ab, row, column );
	stride = count == 1 ? 1 : ab->stride1;
	API_SUFFIX(c_dscal_ndarray)( (CBLAS_INT)count, alpha, ab->data+offset, (CBLAS_INT)stride, 0 );
}

/**
* Performs the pinned fixed-alpha=-1 conditional reference-order GER.
*
* The outer loop always follows original logical Y, including row-major
* storage. Original zero Y skips its column; zero X is not skipped.
* Volatile products retain multiplication rounding before addition.
* Original compact coordinates avoid unchecked difference-stride products.
*/
static void dgbtf2_ger( const intmax_t rows, const intmax_t columns, dgbtf2_view *ab, const intmax_t kv, const intmax_t step ) {
	intmax_t i;
	intmax_t j;
	double y;
	double temp;
	volatile double product;

	if ( rows <= 0 || columns <= 0 ) return;
	for ( j = 0; j < columns; j++ ) {
		y = DGBTF2_CELL( ab, kv-1-j, step+1+j );
		if ( y != 0.0 ) {
			temp = -1.0*y;
			for ( i = 0; i < rows; i++ ) {
				product = DGBTF2_CELL( ab, kv+1+i, step )*temp;
				DGBTF2_CELL( ab, kv+i-j, step+1+j ) += product;
			}
		}
	}
}

#endif // !STDLIB_LAPACK_BASE_DGBTF2_PANEL_H
